DB = Path(__file__).with_name('fraudshield.db')


def connect():
    return sqlite3.connect(DB)


def initialize():
    with connect() as con:
        con.executescript('''
        CREATE TABLE IF NOT EXISTS rules (
            id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL,
            field TEXT NOT NULL, operator TEXT NOT NULL, threshold TEXT NOT NULL,
            action TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
        CREATE TABLE IF NOT EXISTS transactions (
            id INTEGER PRIMARY KEY, created_at TEXT NOT NULL, card_token TEXT NOT NULL,
            mti TEXT NOT NULL, amount REAL NOT NULL, mcc TEXT NOT NULL,
            pos_entry TEXT NOT NULL, merchant TEXT NOT NULL,
            decision TEXT NOT NULL, matched_rules TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS cases (
            id INTEGER PRIMARY KEY, transaction_id INTEGER NOT NULL,
            rule_id INTEGER NOT NULL, rule_name TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'Open', assignee TEXT NOT NULL DEFAULT '',
            notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL,
            UNIQUE(transaction_id, rule_id));
        ''')
        if con.execute('SELECT COUNT(*) FROM rules').fetchone()[0] == 0:
            con.executemany('''INSERT INTO rules
                (name,kind,field,operator,threshold,action,enabled)
                VALUES (?,?,?,?,?,?,1)''', [
                ('High Value Transaction', 'Prevention', 'Amount', '>', '50000', 'Decline'),
                ('Transaction Velocity', 'Detection', 'Velocity (5 min)', '>', '3', 'Alert'),
                ('High-Risk Merchant', 'Detection', 'MCC', 'in', '7995,4829', 'Investigate'),
            ])


def read_df(query, params=()):
    with connect() as con:
        return pd.read_sql_query(query, con, params=params)


def matches(rule, tx, velocity_count):
    field = rule['field']
    value = {'Amount': tx['amount'], 'MCC': tx['mcc'],
             'Velocity (5 min)': velocity_count}.get(field)
    if value is None:
        return False
    operator = rule['operator']
    threshold = rule['threshold']
    try:
        if operator == 'in':
            return str(value) in [v.strip() for v in threshold.split(',')]
        if field == 'MCC':
            if operator == '==':
                return str(value) == threshold.strip()
            return False
        number = float(value)
        target = float(threshold)
        return {'>': number > target, '>=': number >= target,
                '<': number < target, '==': number == target}.get(operator, False)
    except (ValueError, TypeError):
        return False


def process_transaction(tx):
    now = datetime.now(timezone.utc)
    timestamp = now.isoformat()
    cutoff = (now - timedelta(minutes=5)).isoformat()
    with connect() as con:
        previous = con.execute('''SELECT COUNT(*) FROM transactions
            WHERE card_token=? AND created_at>=?''',
            (tx['card_token'], cutoff)).fetchone()[0]
        velocity_count = previous + 1
        con.row_factory = sqlite3.Row
        rules = con.execute('SELECT * FROM rules WHERE enabled=1 ORDER BY id').fetchall()
        matched = [dict(rule) for rule in rules if matches(rule, tx, velocity_count)]
        decision = 'DECLINED' if any(r['kind'] == 'Prevention' and r['action'] == 'Decline'
                                    for r in matched) else 'APPROVED'
        cursor = con.execute('''INSERT INTO transactions
            (created_at,card_token,mti,amount,mcc,pos_entry,merchant,decision,matched_rules)
            VALUES (?,?,?,?,?,?,?,?,?)''',
            (timestamp, tx['card_token'], tx['mti'], tx['amount'], tx['mcc'],
             tx['pos_entry'], tx['merchant'], decision,
             json.dumps([r['name'] for r in matched])))
        tx_id = cursor.lastrowid
        for rule in matched:
            if rule['action'] in ('Alert', 'Investigate'):
                con.execute('''INSERT OR IGNORE INTO cases
                    (transaction_id,rule_id,rule_name,created_at)
                    VALUES (?,?,?,?)''', (tx_id, rule['id'], rule['name'], timestamp))
    return tx_id, decision, matched, velocity_count



