# Demo authentication: salted PBKDF2 password hashes; no plaintext passwords stored.
# This is a local prototype login, not a production identity-management system.
def initialize_auth():
    with connect() as con:
        con.execute("""CREATE TABLE IF NOT EXISTS app_users (
            username TEXT PRIMARY KEY,
            salt TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            iterations INTEGER NOT NULL,
            created_at TEXT NOT NULL
        )""")


def has_account():
    with connect() as con:
        return con.execute('SELECT COUNT(*) FROM app_users').fetchone()[0] > 0


def create_account(username, password):
    salt = secrets.token_bytes(16)
    iterations = 260000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iterations)
    with connect() as con:
        con.execute(
            'INSERT INTO app_users (username,salt,password_hash,iterations,created_at) '
            'VALUES (?,?,?,?,?)',
            (username, salt.hex(), digest.hex(), iterations,
             datetime.now(timezone.utc).isoformat()))


def authenticate(username, password):
    with connect() as con:
        row = con.execute(
            'SELECT salt,password_hash,iterations FROM app_users WHERE username=?',
            (username,)).fetchone()
    if row is None:
        # Perform a comparable hash operation even for an unknown user.
        hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), b'0' * 16, 260000)
        return False
    candidate = hashlib.pbkdf2_hmac(
        'sha256', password.encode('utf-8'), bytes.fromhex(row[0]), int(row[2]))
    return hmac.compare_digest(candidate, bytes.fromhex(row[1]))


initialize_auth()

