# Presentation helpers never modify database columns or stored timestamps.
COLUMN_NAMES = {
    'id':'ID', 'created_at':'Date', 'transaction_id':'Transaction ID',
    'mti':'MTI', 'mcc':'MCC', 'pos_entry':'POS Entry',
    'merchant':'Holder', 'decision':'Status', 'matched_rules':'Matched Rules',
    'card_token':'Card Token', 'rule_id':'Rule ID', 'rule_name':'Rule Name',
    'enabled':'Enabled', 'assignee':'Assignee', 'amount':'Amount',
    'velocity':'Velocity', 'kind':'Type',
}
def display_name(name):
    return COLUMN_NAMES.get(name, str(name).replace('_',' ').title())

def display_table(data):
    """Accessible red-header HTML table; display-only, with escaped cell contents."""
    if data is None or data.empty:
        st.info('No records to display.')
        return
    frame = data.copy()
    if 'created_at' in frame.columns:
        timestamps = pd.to_datetime(frame['created_at'], utc=True, errors='coerce')
        local = timestamps.dt.tz_convert('Asia/Kolkata')
        pos = frame.columns.get_loc('created_at')
        frame = frame.drop(columns=['created_at'])
        frame.insert(pos, 'Date', local.dt.strftime('%d-%m-%Y').fillna('—'))
        frame.insert(pos + 1, 'Time (IST)', local.dt.strftime('%I:%M:%S %p').fillna('—'))
    headers = ''.join('<th scope="col">' + html.escape(display_name(c)) + '</th>'
                      for c in frame.columns)
    rows = []
    for row in frame.itertuples(index=False, name=None):
        cells = []
        for val in row:
            raw = '—' if pd.isna(val) else str(val)
            klass = 'fs-approved' if raw == 'APPROVED' else ('fs-declined' if raw == 'DECLINED' else '')
            cells.append('<td class="' + klass + '">' + html.escape(raw) + '</td>')
        rows.append('<tr>' + ''.join(cells) + '</tr>')
    st.markdown('<div class="fs-table-wrap"><table class="fs-table"><thead><tr>' +
                headers + '</tr></thead><tbody>' + ''.join(rows) +
                '</tbody></table></div>', unsafe_allow_html=True)

