def explain_match(rule, tx, velocity):
    field = rule['field']
    actual = {
        'Amount': tx['amount'],
        'MCC': tx['mcc'],
        'Velocity (5 min)': velocity,
    }.get(field, 'N/A')
    if field == 'Amount':
        actual_text = f"₹{float(actual):,.2f}"
        threshold_text = f"₹{float(rule['threshold']):,.2f}" if rule['operator'] != 'in' else rule['threshold']
    elif field == 'Velocity (5 min)':
        actual_text = f"{actual} transactions"
        threshold_text = f"{rule['threshold']} transactions"
    else:
        actual_text = str(actual)
        threshold_text = rule['threshold']
    operator = 'is one of' if rule['operator'] == 'in' else rule['operator']
    return {
        'Rule': f"R{rule['id']:03d} — {rule['name']}",
        'Field': field,
        'Observed': actual_text,
        'Condition': f"{operator} {threshold_text}",
        'Action': rule['action'],
    }


def show_result(result):
    tx_id, decision, matched, velocity, tx = result
    if decision == 'DECLINED':
        st.error(f"Transaction #{tx_id}: DECLINED")
    else:
        st.success(f"Transaction #{tx_id}: APPROVED (simulated)")
    st.caption(f"ISO 8583 illustrative response: MTI 0110 | DE39 = {'05' if decision == 'DECLINED' else '00'}")
    st.metric('5-minute transaction count for this synthetic card', velocity)
    if matched:
        st.subheader('Why was this decision made?')
        display_table(pd.DataFrame([explain_match(r, tx, velocity) for r in matched]))
        if decision == 'DECLINED':
            st.info('A matched prevention decline rule determined the authorization decision.')
        else:
            st.info('Detection matches create cases without automatically declining this transaction.')
    else:
        st.info('No enabled fraud rules matched this transaction.')
    st.json({
        'transaction_id': tx_id,
        'decision': decision,
        'matched_rules': [f"R{r['id']:03d}: {r['name']}" for r in matched],
        'simulated_response_mti': '0110',
        'simulated_de39': '05' if decision == 'DECLINED' else '00',
    })


with t_simulator:
    st.header('ISO 8583 Authorization Simulator')
    st.caption('Field-based ISO 8583 demo, not a raw network-message parser. Use only synthetic card identifiers.')

    # Presets change form values only; they do not submit a transaction.
    presets = {
        'Normal payment': ('NORMAL_DEMO_01', 1000.0, '5411', '051', 'DEMO_STORE'),
        'High-value payment': ('HIGHVALUE_DEMO_01', 75000.0, '5411', '051', 'DEMO_STORE'),
        'High-risk MCC': ('MCC_DEMO_01', 2000.0, '7995', '051', 'DEMO_MERCHANT'),
        'Velocity test': ('VELOCITY_DEMO_01', 1000.0, '5411', '051', 'DEMO_STORE'),
    }
    st.subheader('One-click demo scenarios')
    cols = st.columns(4)
    for col, (label, values) in zip(cols, presets.items()):
        if col.button(label, key=f'preset_{label}', use_container_width=True):
            st.session_state['demo_card'] = values[0]
            st.session_state['demo_amount'] = values[1]
            st.session_state['demo_mcc'] = values[2]
            st.session_state['demo_pos'] = values[3]
            st.session_state['demo_merchant'] = values[4]
            st.session_state['demo_mti'] = '0100'
            st.session_state.pop('last_result', None)

    with st.form('transaction_form'):
        mti = st.text_input('MTI — Message Type Indicator', '0100', key='demo_mti')
        card_token = st.text_input('DE2 — Synthetic Card Identifier', 'TESTCARD001', key='demo_card')
        amount = st.number_input('DE4 — Transaction Amount (INR)', min_value=0.0,
                                 value=1000.0, key='demo_amount')
        mcc = st.text_input('DE18 — Merchant Category Code (MCC)', '5411', key='demo_mcc')
        pos_entry = st.text_input('DE22 — POS Entry Mode', '051', key='demo_pos')
        merchant = st.text_input('DE42 — Merchant ID', 'MERCHANT001', key='demo_merchant')
        submitted = st.form_submit_button('Process Transaction', type='primary')

    def valid_input():
        return (mti == '0100' and bool(card_token.strip()) and bool(merchant.strip())
                and len(mcc) == 4 and mcc.isdigit())

    if submitted:
        if not valid_input():
            st.error('Use MTI 0100, a nonempty synthetic card ID and merchant ID, and a four-digit MCC.')
        else:
            tx = dict(mti=mti, card_token=card_token.strip(), amount=amount,
                      mcc=mcc, pos_entry=pos_entry, merchant=merchant.strip())
            tx_id, decision, matched, velocity = process_transaction(tx)
            st.session_state['last_result'] = (tx_id, decision, matched, velocity, tx)

    st.divider()
    st.caption('Velocity demo: use a fresh synthetic card identifier if you want a clean 4-transaction example.')
    if st.button('Run 4-transaction velocity burst', type='secondary'):
        if not valid_input():
            st.error('Correct the transaction form fields before running the burst.')
        else:
            tx = dict(mti=mti, card_token=card_token.strip(), amount=amount,
                      mcc=mcc, pos_entry=pos_entry, merchant=merchant.strip())
            results = []
            for _ in range(4):
                tx_id, decision, matched, velocity = process_transaction(tx)
                results.append((tx_id, decision, matched, velocity, tx))
            st.session_state['last_result'] = results[-1]
            st.success('Four simulated transactions were recorded.')
            display_table(pd.DataFrame([
                {'Transaction ID': r[0], 'Status': r[1], '5-Min Count': r[3],
                 'Matched Rules': ', '.join(v['name'] for v in r[2]) or 'None'}
                for r in results
            ]))
            st.caption('The burst is cumulative: existing transactions for this card in the last five minutes also count.')

    if 'last_result' in st.session_state:
        show_result(st.session_state['last_result'])

with t_cases:
    st.header('Fraud Case Management')
    cases = read_df('''SELECT c.id,c.transaction_id,c.rule_name,c.status,
        c.assignee,c.notes,c.created_at FROM cases c ORDER BY c.id DESC''')
    if len(cases):
        display_table(cases)
        case_id = st.selectbox('Choose case', cases['id'].tolist())
        record = cases.loc[cases['id'] == case_id].iloc[0]
        with st.form('case_update'):
            status = st.selectbox('Status', ['Open', 'Investigating', 'Resolved', 'False Positive'],
                                  index=['Open', 'Investigating', 'Resolved', 'False Positive'].index(record['status']))
            assignee = st.text_input('Assigned analyst', record['assignee'])
            notes = st.text_area('Investigation notes', record['notes'])
            if st.form_submit_button('Save case'):
                with connect() as con:
                    con.execute('UPDATE cases SET status=?,assignee=?,notes=? WHERE id=?',
                                (status, assignee, notes, int(case_id)))
                st.success('Case saved. Refresh the page to see the changes.')
    else:
        st.info('No fraud cases yet. Trigger a detection rule in the simulator.')

footer()
